    /** The origin of a module class, defaulting to Meteor for anything not in the ported set. */
    public static ModuleOrigin of(Class<?> klass) {
        return LIQUID_BOUNCE.contains(klass.getSimpleName()) ? ModuleOrigin.LiquidBounce : ModuleOrigin.Meteor;
    }

    /** How many modules were ported, without walking the module list. */
    public static int portedCount() {
        return LIQUID_BOUNCE.size();
    }
